exports.declaration:
[Tool("home/husbandry_facts", Title = "Native herd observations",
            Description = "Read current-map player animals, actual enclosed pen membership, native training progress, pregnancy and parent identities, product readiness and player settings tokens. No grass or future birth is credited as feed or stock.")]
        public async Task<object> Facts(IRimBridgeContext ctx, CancellationToken cancellationToken)

[Tool("home/install", Description = "Inspect or queue installation of exact packed furniture. Use its observed thingId (packed or inner). Omit x/z for status. dryRun=true previews native legality; false queues pawn work. Existing orders elsewhere are refused, not cancelled. The returned inner thingId survives installation.")]
        public async Task<object> Install(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string thingId, int x = -1, int z = -1, int rotation = 0, bool dryRun = true)

[Tool("home/manage_waste", Description = "Preview or prioritize one exact waste haul through native hauling WorkGivers. Preserves player orders, filters and zones. Requires an outdoor destination outside the home area, separated from colony buildings, or native burial in an empty grave. Never deletes items. Rechecks eligibility and destination at dispatch.")]
        public async Task<object> Manage(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string thingId, string pawn, string unwanted = "", string bury = "", bool dryRun = true)

[Tool("home/observation_batch", Title = "Colony observation batch",
            Description = "Read the standard colony observation sections in one request. No orders, selection or clock changes. Retains section diagnostics and before/after ticks; rejects game/map changes. Sections run sequentially, not as an atomic snapshot.")]
        public async Task<object> Observe(IRimBridgeContext ctx, CancellationToken cancellationToken)

[Tool("home/recover_service", Description = "Preview or order one exact repair, breakdown repair or refuel through the native WorkGiver. Honors work settings, allowed areas, forbidden supplies, player jobs and reservations. A receipt is not completed labor.")]
        public async Task<object> Recover(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string thingId, string pawn, string method, bool dryRun = true)

[Tool("home/recovery_area", Description = "Lease an existing wholly roofed allowed area for one colonist during native toxic fallout. Intersects player restrictions by refusing wider areas. Expires after 600 ticks or load; never edits areas or replaces a player override. This is a work-area restriction, not protection from every exposure source.")]
        public async Task<object> Area(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string pawn, int areaId, bool dryRun = true)

[Tool("home/render_demand", Description = "Controller rendering lease. No simulation or game-speed changes. Visible game window always renders.")]
        public async Task<object> Demand(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Keep rendering for this many real seconds; zero only reads status.", DefaultValue = 0)] int seconds = 0)

[Tool("home/roof_support", Description = "Read-only counterfactual support check for one exact native wall. Follows installed roof connectivity and radius while excluding that holder. Does not prove enclosure, escape access, ownership or authorize deconstruction.")]
        public async Task<object> Read(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Exact observed wall Thing ID.")] string target)

[Tool("home/upkeep_home", Description = "Add Home only over the observed bounded footprint of an exact facility or stockpile. Native enclosed roofed rooms may be included. Preserves player removals and pre-observation omissions. Requires unchanged native geometry and area revision; controller must independently prove autonomous ownership. Does not alter allowed areas or perform pawn work.")]
        public async Task<object> Apply(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string target, string shape, long revision, bool dryRun = true)

[Tool("home/video_stream", Description = "Lease raw current-screen video for the local dashboard. Presentation only; no input or simulation changes.")]
        public async Task<object> Stream(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Capture lease in real seconds, 0 stops capture.", DefaultValue = 8)] int seconds = 8)

[Tool("home/waste_state", Description = "Read exact visible waste identities and containment. Rotten anonymous animal corpses and spoiled goods are automatic candidates. Other unwanted items require exact unwanted IDs. Forbidden, quest, named/colony corpses, held possessions and graves are protected. Relocation is not destruction.")]
        public async Task<object> State(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string unwanted = "", string bury = "")

[Tool("test/campaign_metrics_fixture", Description = "Prepare disposable campaign metric cases; test builds only.")]
        public async Task<object> Run(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "sleep prepares the fixture; work enables ordinary hauling/construction.")] string action = "sleep")

[Tool("test/comfort_inputs", Description = "Supply disposable construction wood, or prepare hunger/recreation needs after furniture construction. Does not place furniture or order its use.")]
        public async Task<object> Inputs(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Prepare needs only after ordinary furniture construction.", DefaultValue = false)] bool needs = false)

[Tool("test/finish_saved_quantity", Description = "Move exact surviving disposable fixture portions after load to verify saved quantity identities. Does not certify pawn hauling.")]
        public async Task<object> FinishSavedQuantity(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Saved fixture tracking ID.")] string tracking)

[Tool("test/food_observe", Description = "Read ordinary native ingestion and retained food rot state. Test-only; never changes food, pawns, temperatures or time.")]
        public async Task<object> Observe(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Optional spawned food thingId to retain for later rot observation.")] string target = "")

[Tool("test/gear_fixture", Description = "Set up disposable apparel acceptance conditions.")]
        public async Task<object> Setup(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "setup, force, unforce, forbid, allow, policy or interrupt")] string mode = "setup")

[Tool("test/guarded_construction_control", Description = "UNSAFE FOR MODEL EXECUTION. Private prepared-fixture controls: cancel one exact WoodLog Wall blueprint on a returned site using Designator_Cancel; toggle the prepared pawn's actual drafted state; or issue a native ordered Goto. No suppression of game methods or authority hooks.")]
        public async Task<object> Control(IRimBridgeContext ctx,CancellationToken cancellationToken,string operation,
            string colonyId,string loadToken,int mapId,string pawnId=null,string blueprintId=null,int x=0,int z=0)

[Tool("test/interruption_letter", Description = "Disposable letter delivery through the real LetterStack callback; no pawn or simulation edits.")]
        public async Task<object> Run(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string definition = "ThreatBig", string after = "none", string label = "Interruption acceptance", int delayTicks = 0)

[Tool("test/medical_management_change", Description = "Disposable shortage fixture: forbid or restore medicine, draft or release the available doctors. No treatment outcomes injected.")]
        public async Task<object> Change(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "supplies-off, supplies-on, doctors-off or doctors-on.")] string op)

[Tool("test/mining_fixture", Description = "Disposable surface deposit fixture; never installed for gameplay.")]
        public async Task<object> Setup(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string action = "setup", int x = 0, int z = 0)

[Tool("test/modal_fixture", Description = "Disposable native dialog setup and game-value readback.")]
        public async Task<object> Run(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string action = "read", string kind = "zone")

[Tool("test/mood_setup", Description = "Seed deficient needs in one disposable pawn; test builds only.")]
        public async Task<object> Setup(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "food, rest, joy, forced, schedule or mental.")] string scenario)

[Tool("test/population_setup", Description = "Disposable population fixture, excluded from production and model access. Prepares a downed hostile candidate, prison, spare housing and supplies. Does not capture or recruit.")]
        public async Task<object> Setup(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Native starting candidate kind: Villager for resistance work or SpaceRefugee_Clothed for bounded admission.")] string candidateKind = "Villager")

[Tool("test/replace_lineage_wall", Description = "Replace one exact disposable completed wall with an identical independent wall, to test that coordinates cannot transfer construction ownership.")]
        public async Task<object> Replace(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Exact completed fixture wall ID.")] string target)

[Tool("test/settle_caravan", Description = "Disposable multi-map acceptance through the enabled native settle command. Requires the private profile's ordinary multiple-settlement setting. Does not create maps or relocate pawns directly.")]
        public async Task<object> Settle(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string caravanId = null, bool dryRun = true)

[Tool("test/sleeping_need", Description = "Prepare low rest on an exact disposable test colonist.")]
        public async Task<object> Need(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Exact fixture pawn ID.")] string pawn)

[Tool("test/storeroom_setup", Description = "Prepare disposable open ground, wood, exposed medicine and enabled builders. No room or roof is created.")]
        public async Task<object> Setup(IRimBridgeContext ctx, CancellationToken cancellationToken,
            [ToolParameter(Description = "Inject one native construction fumble into a tracked frame.", DefaultValue = false)] bool constructionFailure = false)

[Tool("test/throughput_event", Description = "Disposable tick-scheduled native pause, speed change or animal mental-state onset; excluded from production builds.")]
        public async Task<object> Run(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string op = "status", int afterTicks = 7)

[Tool("test/trade_fixture", Description = "Disposable trade acceptance setup/readback; excluded from production builds and model execution.")]
        public async Task<object> Run(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string action = "snapshot", string traderId = null, string pawnId = null)

[Tool("test/trade_quest_offer", Description = "Disposable ordinary TradeRequest or ThreatReward_Raid_Joiner offer at native storyteller points; never awards completion or edits quest states or expiration.")]
        public async Task<object> TradeQuest(IRimBridgeContext ctx, CancellationToken cancellationToken, bool dryRun = true,
            string definition = "TradeRequest")

[Tool("test/world_incident", Description = "Disposable ordinary ColdSnap or AnimalInsanitySingle incident at native storyteller settings. No direct condition, temperature, pawn or health edits.")]
        public async Task<object> WorldIncident(IRimBridgeContext ctx, CancellationToken cancellationToken,
            string definition, bool dryRun = true)
